use std::path::{Path, PathBuf};

use anyhow::Result;
use ignore::WalkBuilder;

use super::language::Language;

const SKIPPED_DIRS: &[&str] = &[
    ".git",
    ".callsieve",
    "node_modules",
    "target",
    "dist",
    "build",
    "coverage",
    "vendor",
];

const SKIPPED_FILES: &[&str] = &[
    "cargo.lock",
    "package-lock.json",
    "pnpm-lock.yaml",
    "yarn.lock",
    "deno.lock",
];

pub fn source_files(root: &Path) -> Result<Vec<PathBuf>> {
    let mut files = Vec::new();

    for entry in WalkBuilder::new(root)
        .standard_filters(true)
        .hidden(false)
        .require_git(false)
        .build()
    {
        let entry = match entry {
            Ok(entry) => entry,
            Err(_) => continue,
        };
        let path = entry.path();

        if should_skip(path)
            || !entry
                .file_type()
                .is_some_and(|file_type| file_type.is_file())
        {
            continue;
        }

        let Ok(relative) = path.strip_prefix(root) else {
            continue;
        };

        if is_skipped_file(relative) {
            continue;
        }

        if Language::from_path(relative).is_some() {
            files.push(relative.to_path_buf());
        }
    }

    files.sort();
    Ok(files)
}

fn should_skip(path: &Path) -> bool {
    path.components().any(|component| {
        let value = component.as_os_str().to_string_lossy();
        SKIPPED_DIRS
            .iter()
            .any(|skipped| value.eq_ignore_ascii_case(skipped))
    })
}

fn is_skipped_file(path: &Path) -> bool {
    if is_generated_trace_file(path) {
        return true;
    }

    let Some(file_name) = path.file_name().and_then(|name| name.to_str()) else {
        return false;
    };

    SKIPPED_FILES
        .iter()
        .any(|skipped| file_name.eq_ignore_ascii_case(skipped))
}

fn is_generated_trace_file(path: &Path) -> bool {
    let normalized = path
        .to_string_lossy()
        .replace('\\', "/")
        .to_ascii_lowercase();
    if !normalized.starts_with("benchmarks/") {
        return false;
    }

    let Some(file_name) = path.file_name().and_then(|name| name.to_str()) else {
        return false;
    };
    let file_name = file_name.to_ascii_lowercase();
    file_name.ends_with("-trace.json") || file_name.starts_with("session-trace")
}

